<?php
namespace App\Http\Controllers; use App\Models\{CashierShift,Payment}; use App\Enums\PaymentStatus; use Illuminate\Http\Request; use Illuminate\Support\Str;
class CashierShiftController extends Controller { public function index(Request $r){$pid=$r->user()->property_id;$open=CashierShift::where('property_id',$pid)->where('user_id',$r->user()->id)->where('status','open')->first();$shifts=CashierShift::with('user')->where('property_id',$pid)->latest('opened_at')->paginate(20);return view('cashier-shifts.index',compact('open','shifts'));} public function open(Request $r){abort_if(CashierShift::where('user_id',$r->user()->id)->where('status','open')->exists(),422,'You already have an open shift.');$d=$r->validate(['opening_cash'=>'required|numeric|min:0','opening_notes'=>'nullable|max:1000']);CashierShift::create(['property_id'=>$r->user()->property_id,'user_id'=>$r->user()->id,'shift_number'=>'SHIFT-'.now()->format('YmdHis').'-'.strtoupper(Str::random(4)),'status'=>'open','opening_cash'=>$d['opening_cash'],'opened_at'=>now(),'opening_notes'=>$d['opening_notes']??null]);return back()->with('success','Cashier shift opened.');} public function close(Request $r,CashierShift $shift){abort_unless($shift->property_id===$r->user()->property_id && $shift->user_id===$r->user()->id,403);abort_unless($shift->status==='open',422,'Shift is already closed.');$d=$r->validate(['closing_cash'=>'required|numeric|min:0','closing_notes'=>'nullable|max:1000']);$cash=Payment::where('property_id',$shift->property_id)->where('received_by',$shift->user_id)->where('method','cash')->where('status',PaymentStatus::Successful)->whereBetween('paid_at',[$shift->opened_at,now()])->sum('amount');$expected=(float)$shift->opening_cash+(float)$cash;$shift->update(['status'=>'closed','expected_cash'=>$expected,'closing_cash'=>$d['closing_cash'],'variance'=>$d['closing_cash']-$expected,'closed_at'=>now(),'closing_notes'=>$d['closing_notes']??null]);return back()->with('success','Cashier shift closed and reconciled.');} }
